          "passage": "【A】\n先日、友人が「ここ10年ほど映画館に行っていない」と言った。それを聞いて非常に驚いた。映画は見るが、インターネットの動画配信や、テレビ、DVDなどで見るだけだそうだ。私も映画館以外で見ることもあるが、スマホを見てしまったり、おなかが空いたら冷蔵庫を開けてしまったりもした。また、宅配業者が来て一時停止せざるを得ないこともある。これでは映画に集中ができない。気が散ってしまったためか、そうして見た映画は内容を覚えていない部分もある。映画館で見ると、最初から最後まで集中して、しっかりと楽しむことができる。そのため、内容はよく覚えている。これからもできるだけ映画館で見たいと思っている。\n\n【B】\n映画館で映画を見ると、ほかのことができず、その世界に入り込んで夢中になれるから好きだ。一方、動画配信サービスなどを使い、映画館以外の場所で見るのも好きだ。話の展開がゆっくりになったときは少し退屈になり、スマホを見ながら映画を見ることもある。これは映画館ではできないことだ。また、聞き逃したときや、理解できなかった台詞をもう一度聞くこともできるし、見るのに疲れたら休んで、別の日に見ることだってできる。先日も夜中に映画を見始めて、途中で寝てしまった。次の日に続きを見ることもできた。集中して見るのもいいが、自分のペースで見られるのも便利だと思う。",
