          "passage": "【文章作成サポートのご案内】\n国際センターでは、留学生のみなさんの日本語文章作成を支援するため、訓練を受けた大学院生が文章作成サポートを行います。\n\n場所：国際センター（5号館）2階 203教室\n開室曜日：授業期間中の 火・木・金曜日\n利用時間：①〜⑥の時間から、1日につき1回\n  ① 11:40〜12:30   ④ 16:00〜16:50\n  ② 14:00〜14:50   ⑤ 17:00〜17:50\n  ③ 15:00〜15:50   ⑥ 18:00〜18:50\n\n利用資格：本学の留学生なら誰でも利用できます。\n\nサポートの内容：\n  日本語のアカデミックな文章の作成を支援します。\n  【対象になる文章】\n  ・日本語で書かれたアカデミックな文章\n    例）授業の課題やレポート、卒業論文、研究計画書\n  【対象にならない文章】\n  ・外国語を翻訳した日本語の文章\n  ・履歴書など就職関連の文章\n\n利用方法：\n・予約の申し込みは実施日の2週間前から前日の昼12時までメールで受け付けます。\n  氏名・所属・相談内容・携帯電話番号・希望日時（できれば第3希望まで）を書いて、下記のアドレスに送信してください。折り返し、確定した日時をメールで返信します。\n・一度にできる予約は1回分です。次回の予約ができるのは、予約した回が終了した後になります。\n・予約した時間に連絡なく15分以上遅れた場合はキャンセルとなります。\n・当日は、支援を受けたい文章を2部印刷して持参してください。\n・予約が入っていない時間帯がある場合に限り、当日利用が可能です。直接来室して確認してください。\n\n大石大学国際センター 文章作成サポート室\nbunshou@ooishi.ac.jp / 021-543-0001",
          "sentence": "次の4人は、全員大石大学の留学生であり、文章作成サポートを受けたいと考えている。この中で、このサポートを受けられるのは誰か。<br><br>• <b>ミウンさん:</b> 就職活動用の履歴書（希望曜日: 月曜か火曜）<br>• <b>ラウラさん:</b> 卒業論文（希望曜日: 月曜か水曜）<br>• <b>ジョンさん:</b> 授業の課題レポート（希望曜日: 木曜）<br>• <b>グエンさん:</b> ベトナム語の文献を翻訳した文章（希望曜日: 火曜か木曜）",
